//
// The Railway service behind https://ujira.co. Generated by `railway config migrate`
// from railway.json, then completed so that it states everything the live service
// runs with. Preview with `railway config plan` before every `railway config apply`.
//
// Variables are not managed here: they hold the testnet keys and the mandate, and
// stay in Railway. The image's own ENTRYPOINT and CMD start the server, so there is
// no start command, and PORT=8080 comes from the Dockerfile.

import { defineRailway, project, service, volume, type ProjectDefinition } from 'railway/iac';

// The CLI reads `variables` from the project definition, but the SDK types do not
// list it yet. Without `managed: false` the plan refuses to run.
type Definition = Omit<ProjectDefinition, 'name'> & { variables: { managed: boolean } };

// Only the resources listed here belong to this file, so a resource it leaves out
// is never deleted by an apply.
export const partial = 'ujira-mcp';

export default defineRailway(() => {
  // Holds receipts.json (UJIRA_RECEIPTS_FILE) across deploys.
  const data = volume('ujira-mcp-volume', {
    region: 'us-east4-eqdc4a',
    sizeMB: 5000,
    allowOnlineResize: true,
    alerts: { usage: { '80': {}, '95': {}, '100': {} } },
  });

  const ujiraMcp = service('ujira-mcp', {
    build: { buildEnvironment: 'V3', builder: 'DOCKERFILE', dockerfilePath: 'Dockerfile' },
    deploy: {
      healthcheckPath: '/healthz',
      healthcheckTimeout: 60,
      restartPolicyType: 'ON_FAILURE',
      restartPolicyMaxRetries: 10,
    },
    replicas: { 'us-east4-eqdc4a': 1 },
    networking: {
      serviceDomains: { 'ujira-mcp-production.up.railway.app': {} },
      customDomains: { 'ujira.co': { port: 8080 }, 'www.ujira.co': { port: 8080 } },
    },
    volumeMounts: { '/data': data },
  });

  const definition: Definition = {
    variables: { managed: false },
    resources: [ujiraMcp, data],
  };
  return project('ujira-mcp', definition);
});
